/// Lightweight IVC verifier carrying:
/// - the application context (for the decider check),
/// - the self-verifying key,
/// - the SRS verifier parameters (for the pairing check).
///
/// Returned by [`super::setup()`].
#[derive(Clone, Debug)]
pub struct IvcVerifier<T: Ivc> {
    pub(crate) ctx: T::Context,
    pub(crate) vk: MidnightVK,
    pub(crate) params_verifier: ParamsVerifierKZG<E>,
}

impl<T: Ivc> IvcVerifier<T> {
    /// Verifies an IVC proof against the given instance.
    ///
    /// Checks that the proof is valid with respect to the given instance by:
    /// 1. Preparing the proof to obtain a proof accumulator.
    /// 2. Accumulating it with the instance's accumulator.
    /// 3. Checking the pairing invariant on the result.
    /// 4. Running the application-level [`decider`](super::IvcState::decider)
    ///    on the instance state.
    ///
    /// This method checks that `instance.vk_repr` matches the canonical
    /// verifying key held by this verifier (derived from
    /// [`setup`](super::setup())). Without this check, a proof generated
    /// under a different (potentially malicious) circuit could pass
    /// verification.
    pub fn verify(&self, instance: &IvcInstance<T>, proof: &[u8]) -> Result<(), IvcError> {
        // Reject proofs whose instance claims a different verifying key.
        if instance.vk_repr != self.vk.vk().transcript_repr() {
            return Err(IvcError::VkMismatch);
        }

        if !T::decider(&self.ctx, &instance.state) {
            return Err(IvcError::DeciderFailed);
        }

        let fixed_bases = midnight_circuits::verifier::fixed_bases::<S>(self.vk.vk());

        let pi =
            IvcCircuit::<T>::format_instance(instance).map_err(|_| IvcError::InvalidInstance)?;

        let mut transcript = CircuitTranscript::<PoseidonState<F>>::init_from_bytes(proof);
        let dual_msm =
            plonk::prepare::<F, KZGCommitmentScheme<E>, CircuitTranscript<PoseidonState<F>>>(
                self.vk.vk(),
                &[KZGMultiCommitment::commitment_to_zero(
                    PolynomialLabel::CommittedInstance(0),
                )],
                &[&pi],
                &mut transcript,
            )
            .map_err(|_| IvcError::InvalidProof)?;

        transcript.assert_empty().map_err(|_| IvcError::TranscriptNotEmpty)?;

        let proof_acc = Accumulator::from_dual_msm(dual_msm, &fixed_bases);

        // Verify that both `proof_acc` and `instance.acc` satisfy the pairing
        // invariant, with a single pairing, by accumulating them first.
        let final_acc = Accumulator::<S>::accumulate(&[proof_acc, instance.acc.clone()]);
        if !final_acc.check(&self.params_verifier, &fixed_bases) {
            return Err(IvcError::InvalidProof);
        };

        Ok(())
    }
}

/// Contains:
/// - a commitment to the verifying key (of the IVC circuit itself),
/// - the current state (after the latest transition),
/// - the accumulator (that summarises all prior steps).
///
/// **Important:** the `vk_repr` field must **not** be trusted as-is. The
/// verifier must compare it against the canonical `vk_repr` obtained by
/// running [`setup`](super::setup()).
/// See [`IvcVerifier::verify`](super::IvcVerifier::verify) for details.
#[derive(Clone, Debug)]
pub struct IvcInstance<T: Ivc> {
    pub(crate) vk_repr: F,
    pub(crate) state: T::State,
    pub(crate) acc: Accumulator<S>,
}

impl<T: Ivc> IvcInstance<T> {
    /// Returns the current state.
    pub fn state(&self) -> &T::State {
        &self.state
    }
}

/// The private witness for a single IVC step.
///
/// Contains:
/// - a previous state (input to the transition),
/// - a previous accumulator (summarises all steps up to the previous state),
/// - a proof asserting the validity of the previous step (if not genesis),
/// - a transition witness (input that drives the state change).
#[derive(Clone, Debug)]
pub struct IvcWitness<T: Ivc> {
    pub(crate) prev_state: T::State,
    pub(crate) prev_acc: Accumulator<S>,
    pub(crate) prev_proof: Vec<u8>,
    pub(crate) transition_witness: T::Witness,
}

fn used_chips(&self) -> ZkStdLibArch {
    Self::arch()
}

fn format_instance(instance: &Self::Instance) -> Result<Vec<F>, IvcError> {
    Ok([
        vec![instance.vk_repr],
        T::format_public_input(&instance.state),
        AssignedAccumulator::<S>::as_public_input(&instance.acc),
    ]
    .concat())
}

    fn genesis(ctx: &Self::Context) -> Self::State;

    /// Off-circuit check that the state meets the required invariants.
    ///
    /// Automatically called by [`IvcVerifier::verify`] to check any
    /// properties that are deferred to off-circuit verification, such as
    /// accumulator validity or hash-chain integrity.
    ///
    /// In particular, when [`State`](Self::State) contains data that
    /// does not appear directly in [`AssignedState`](Self::AssignedState)
    /// but only through a hash or commitment, this function must verify
    /// that the summary stored in [`State`](Self::State) (e.g. a hash
    /// field) is consistent with the full data it summarises.
    ///
    /// Returns `true` if the state passes all checks.
    fn decider(ctx: &Self::Context, state: &Self::State) -> bool;
}

/// Input/output interface for IVC state values.
///
/// Bridges [`State`](IvcState::State) and
/// [`AssignedState`](IvcState::AssignedState): assigning native values into the
/// circuit, constraining them as public inputs, and formatting them as
/// raw native field elements for the public-input vector.
pub trait IvcIO: IvcState {
    /// Assigns a [`State`](IvcState::State) value as a private input,
    /// producing the corresponding [`AssignedState`](IvcState::AssignedState).
    ///

    /// accumulation after `collapse()` has been called off-circuit.
    ///
    /// # Errors
    ///
    /// If the expected shape is not satisfied.
    pub fn assign_collapsed_accumulator(
        &self,
        layouter: &mut impl Layouter<S::F>,
        fixed_base_labels: &[PolynomialLabel],
        value: Value<Accumulator<S>>,
    ) -> Result<AssignedAccumulator<S>, Error> {
        let acc = AssignedAccumulator::assign(
            layouter,
            &self.curve_chip,
            &self.scalar_chip,
            &[PolynomialLabel::NoLabel],
            &[fixed_base_labels, &[PolynomialLabel::NoLabel]].concat(),
            &HashSet::new(),
            &fixed_base_labels.iter().cloned().collect(),
            value,
        )?;

        Ok(acc)
    }

    /// Accumulates several accumulators together. The resulting acc will
    /// satisfy the invariant iff all the accumulators individually do.
    pub fn accumulate(
        &self,
        layouter: &mut impl Layouter<S::F>,
        accs: &[AssignedAccumulator<S>],
    ) -> Result<AssignedAccumulator<S>, Error> {
        AssignedAccumulator::<S>::accumulate(
            layouter,
            self,
            &self.scalar_chip,
            &self.sponge_chip,
            accs,
        )
    }
}

impl<S: SelfEmulation> VerifierGadget<S> {
    /// Assigns a verifying key as a public input. All the necessary information
    /// is required off-circuit, except for the `transcript_repr` value.
    pub fn assign_vk_as_public_input<PCS: InCircuitPCS<S>>(
        &self,
        layouter: &mut impl Layouter<S::F>,
        domain: &EvaluationDomain<S::F>,
        cs: &ConstraintSystem<S::F>,
        transcript_repr_value: Value<S::F>,
    ) -> Result<AssignedVk<S, PCS>, Error> {
        let transcript_repr: AssignedNative<S::F> =
            self.scalar_chip.assign_as_public_input(layouter, transcript_repr_value)?;

        // We expect a finalized cs with no selectors, i.e. whose selectors have been
        // converted into fixed columns. In the context of IVC, the constraint system
        // might still contain selectors.
        let cs = if cs.num_selectors() > 0 {
            let selectors = vec![vec![false]; cs.num_selectors()];
            cs.clone().directly_convert_selectors_to_fixed(selectors).0
        } else {
            cs.clone()
        };

        let fixed_commitments = (0..cs.num_fixed_columns() + cs.num_selectors())
            .map(|i| PCS::fixed_commitment(PolynomialLabel::Fixed(i)))
            .collect();

        let perm_commitments = (0..cs.permutation().columns.len())
            .map(|i| PCS::fixed_commitment(PolynomialLabel::PermutationFixed(i)))
            .collect();

        let assigned_vk = AssignedVk {
            domain: domain.clone(),
            fixed_commitments,
            perm_commitments,
            cs: cs.clone(),
            cs_degree: cs.degree(),
            transcript_repr,
        };

        Ok(assigned_vk)
    }

    /// Assigns a verifying key as a constant. All the necessary information is
    /// available off-circuit, except for the `transcript_repr` which is
    /// "assigned fixed".
    pub fn assign_fixed_vk<PCS: InCircuitPCS<S>>(
        &self,
        layouter: &mut impl Layouter<S::F>,
        domain: &EvaluationDomain<S::F>,
        cs: &ConstraintSystem<S::F>,
        transcript_repr_constant: S::F,
    ) -> Result<AssignedVk<S, PCS>, Error> {
        let transcript_repr = self.scalar_chip.assign_fixed(layouter, transcript_repr_constant)?;

        let fixed_commitments = (0..cs.num_fixed_columns() + cs.num_selectors())
            .map(|i| PCS::fixed_commitment(PolynomialLabel::Fixed(i)))
            .collect();

        let perm_commitments = (0..cs.permutation().columns.len())
            .map(|i| PCS::fixed_commitment(PolynomialLabel::PermutationFixed(i)))
            .collect();

        let assigned_vk = AssignedVk {
            domain: domain.clone(),
            fixed_commitments,
            perm_commitments,
            cs: cs.clone(),
            cs_degree: cs.degree(),
            transcript_repr,
        };

        Ok(assigned_vk)
    }
}

    /// Prepares a plonk proof into a PCS instance that can be finalized or
    /// batched. It is responsibility of the verifier to check the validity of
    /// the instance columns. It is the in-circuit analog of "prepare" from
    /// midnight-proofs at src/plonk/verifier.rs.
    ///
    /// The proof is considered to be valid if the resulting accumulator
    /// satisfies the [invariant](crate::verifier::Accumulator::check)
    /// with respect to the relevant `tau_in_g2`.
    pub fn prepare<PCS: InCircuitPCS<S>>(
        &self,
        layouter: &mut impl Layouter<S::F>,
        assigned_vk: &AssignedVk<S, PCS>,
        assigned_committed_instances: &[PCS::AssignedCommitment],
        assigned_instances: &[&[AssignedNative<S::F>]],
        proof: Value<Vec<u8>>,
    ) -> Result<AssignedAccumulator<S>, Error> {
        let (trace, transcript) = self.parse_trace(
            layouter,
            assigned_vk,
            assigned_committed_instances,
            assigned_instances,
            proof,
        )?;

        self.verify_algebraic_constraints(
            layouter,
            assigned_vk,
            trace,
            assigned_committed_instances,
            assigned_instances,
            transcript,
        )
    }
}

    &mut self,
    layouter: &mut impl Layouter<S::F>,
    proof: Value<Vec<u8>>,
) -> Result<(), Error> {
    self.sponge_state = Some(self.sponge_chip.init(layouter, None)?);

    // Unwrapping the witness. The amount of points read from the proof is
    // fixed for a given `Architecture`, and does not depend on the size of
    // the proof.
    // The caveat with this approach is that our in-circuit verifier will not
    // be able to verify that the proof did not include extra bytes after
    // all the relevant bytes have been read. This is not an issue anyway.
    let mut proof_bytes = Vec::new();
    proof.clone().map(|pi| proof_bytes.extend_from_slice(&pi));
    self.transcript_reader = Some(CircuitTranscript::init_from_bytes(&proof_bytes));

    Ok(())
}

/// Absorbs a scalar into the transcript.
pub fn common_scalar(
    &mut self,
    layouter: &mut impl Layouter<S::F>,
    scalar: &AssignedNative<S::F>,
) -> Result<(), Error> {

    ///
    /// # Warning
    ///
    /// The received points are not enforced to be in the prime-order subgroup.
    pub fn read_commitment(
        &mut self,
        layouter: &mut impl Layouter<S::F>,
        labels: &[PolynomialLabel],
    ) -> Result<AssignedKZGMultiCommitment<S>, Error> {
        let mut inners = Vec::with_capacity(labels.len());
        for label in labels {
            let reader =
                self.transcript_reader.as_mut().expect("You must init the transcript gadget");
            // If an error, do not fail, assign a default commitment instead.
            // (This allows us to parse dummy proofs.)
            let point: Value<S::C> = match reader.read::<S::C>() {
                Ok(point) => Value::known(point),
                Err(_) => Value::known(S::C::default()),
            };
            let assigned_point =
                S::assign_without_subgroup_check(layouter, &self.curve_chip, point)?;
            inners.push(AssignedKZGCommitment::simple(assigned_point, label.clone()));
        }

        let assigned_com = AssignedKZGMultiCommitment(inners);
        self.common_commitment(layouter, &assigned_com)?;

        Ok(assigned_com)
    }

    /// Reads a scalar from the reader buffer, and adds it to the transcript.
    /// Think of the read scalar as a witness freely chosen by the prover.
    pub fn read_scalar(
        &mut self,
        layouter: &mut impl Layouter<S::F>,
    ) -> Result<AssignedNative<S::F>, Error> {
        let reader = self.transcript_reader.as_mut().expect("You must init the transcript gadget");
        // If an error, do not fail, assign a default scalar instead.
        // (This allows us to parse dummy proofs.)
        let scalar: Value<S::F> = match reader.read::<S::F>() {
            Ok(scalar) => Value::known(scalar),
            Err(_) => Value::known(S::F::ZERO),
        };

        let assigned_scalar = self.scalar_chip.assign(layouter, scalar)?;
        self.common_scalar(layouter, &assigned_scalar)?;

        Ok(assigned_scalar)
    }
}

